package com.hms.followups;
import com.hms.appointments.*; import com.hms.doctors.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/follow-ups") public class FollowUpController{private final TenantRepository tenants;private final PatientRepository patients;private final AppointmentRepository appointments;private final DoctorRepository doctors;private final FollowUpRepository followUps;public FollowUpController(TenantRepository t,PatientRepository p,AppointmentRepository a,DoctorRepository d,FollowUpRepository f){tenants=t;patients=p;appointments=a;doctors=d;followUps=f;}
 @GetMapping public List<FollowUp> list(@PathVariable String tenantSlug){return followUps.findAllByTenantIdOrderByRecommendedFromAsc(tenant(tenantSlug));}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public FollowUp create(@PathVariable String tenantSlug,@Valid @RequestBody CreateFollowUpRequest r){UUID t=tenant(tenantSlug);Patient p=patients.findById(r.patientId()).orElseThrow(()->new IllegalArgumentException("Patient not found"));if(!p.getTenantId().equals(t))throw new IllegalArgumentException("Patient does not belong to hospital");if(r.sourceAppointmentId()!=null){Appointment a=appointments.findById(r.sourceAppointmentId()).orElseThrow(()->new IllegalArgumentException("Appointment not found"));if(!a.getTenantId().equals(t))throw new IllegalArgumentException("Appointment does not belong to hospital");}if(r.doctorId()!=null){Doctor d=doctors.findById(r.doctorId()).orElseThrow(()->new IllegalArgumentException("Doctor not found"));if(!d.getTenantId().equals(t))throw new IllegalArgumentException("Doctor does not belong to hospital");}if(r.recommendedTo()!=null&&r.recommendedFrom()!=null&&r.recommendedTo().isBefore(r.recommendedFrom()))throw new IllegalArgumentException("recommendedTo must not be before recommendedFrom");return followUps.save(new FollowUp(t,r));}
 @PatchMapping("/{followUpId}/status") public FollowUp status(@PathVariable String tenantSlug,@PathVariable UUID followUpId,@Valid @RequestBody UpdateFollowUpStatusRequest r){FollowUp f=followUps.findById(followUpId).orElseThrow(()->new IllegalArgumentException("Follow-up not found"));if(!f.getTenantId().equals(tenant(tenantSlug)))throw new IllegalArgumentException("Follow-up does not belong to hospital");f.updateStatus(r.status());return followUps.save(f);}
 private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
